use flypow_service_core::*;
fn k(n:u8)->Key{[n;32]}
fn version()->Version{Version{id:k(1),artifact:k(2),policy:k(3),basis:[6000,2500,500,1000],shares:vec![Share{entitlement:k(4),beneficiary:k(5),units:2,claimed:Amount(0),beneficiary_sequence:0},Share{entitlement:k(6),beneficiary:k(7),units:98,claimed:Amount(0),beneficiary_sequence:0}],payees:[k(8),k(9),k(10)],matured:Amount(0),paid:[Amount(0);4],released:true}}
fn funded(total:u128)->Ledger{let mut l=Ledger::default();l.apply(k(100),Operation::Publish{version:version()},0).unwrap();l.apply(k(101),Operation::Deposit{customer:k(11),wallet:k(12),amount:Amount(total)},total).unwrap();l.apply(k(102),Operation::Authorize{allowance:Allowance{id:k(13),customer:k(11),session:k(14),version:k(1),price_policy:k(15),limit:Amount(total),used:Amount(0),reserved:Amount(0),expires:100,revoked:false}},total).unwrap();l}
fn consume(l:&mut Ledger,total:u128,amount:u128){l.apply(k(103),Operation::Reserve{order:k(16),allowance:k(13),request:k(17),amount:Amount(amount),now:1},total).unwrap();l.apply(k(104),Operation::Consume{order:k(16),receipt:k(18)},total).unwrap();}
#[test]fn amount_identity_and_burn(){for s in ["", "-1","01","1.0","1e8","340282366920938463463374607431768211456"]{assert!(atoms(s).is_err());}assert_eq!(atoms("340282366920938463463374607431768211455").unwrap(),u128::MAX);assert_eq!(serde_json::to_string(&Amount(1)).unwrap(),"\"1\"");assert!(serde_json::from_str::<Amount>("1").is_err());let a=Asset{genesis:k(1),issuance_program:k(2),service_program:k(3),token_program:k(4),mint:k(5),vault:k(6),vault_authority:k(7),policy:k(8),decimals:8,production:false};let mut o=MintObservation{asset:a.clone(),supply:CAP-100,initialized:true,issued_cap:CAP,issuance_record_verified:true,mint_authority_revoked:true,freeze_authority_revoked:true};assert!(a.verify(&o,false).is_ok());o.supply=CAP+1;assert!(a.verify(&o,false).is_err());o.supply=CAP;o.asset.mint=k(9);assert!(a.verify(&o,false).is_err());assert!(a.verify(&o,true).is_err());}
#[test]fn shared_vault_cannot_cover_debts_twice(){let mut l=funded(100);let before=borsh::to_vec(&l).unwrap();assert!(l.apply(k(19),Operation::Deposit{customer:k(20),wallet:k(21),amount:Amount(100)},100).is_err());assert_eq!(before,borsh::to_vec(&l).unwrap());assert!(l.apply(k(19),Operation::Deposit{customer:k(20),wallet:k(21),amount:Amount(100)},200).is_ok());assert_eq!(l.obligations().unwrap(),200);assert!(l.validate(199).is_err());assert!(l.validate(210).is_ok());assert_eq!(l.customers[0].available,Amount(100));}
#[test]fn frozen_request_retry_revoke_refund_and_unknown_funds(){let mut l=funded(100);let op=Operation::Reserve{order:k(16),allowance:k(13),request:k(17),amount:Amount(60),now:1};assert!(l.apply(k(103),op.clone(),100).unwrap());assert!(!l.apply(k(103),op,100).unwrap());assert!(l.apply(k(103),Operation::Reserve{order:k(16),allowance:k(13),request:k(17),amount:Amount(61),now:1},100).is_err());assert!(l.apply(k(22),Operation::Withdraw{customer:k(11),wallet:k(12),amount:Amount(41)},59).is_err());l.apply(k(23),Operation::Revoke{allowance:k(13)},100).unwrap();assert!(l.apply(k(24),Operation::Reserve{order:k(25),allowance:k(13),request:k(26),amount:Amount(1),now:2},100).is_err());l.apply(k(27),Operation::Refund{order:k(16),amount:Amount(60)},100).unwrap();assert!(l.apply(k(28),Operation::Refund{order:k(16),amount:Amount(60)},100).is_err());assert!(l.apply(k(29),Operation::Mature{order:k(16),amount:Amount(1)},100).is_err());assert_eq!(l.customers[0].available,Amount(100));}
#[test]fn cumulative_claims_wallet_migration_and_retirement(){let total=100_000u128*100_000_000;let mut l=funded(total);consume(&mut l,total,total);l.apply(k(30),Operation::Mature{order:k(16),amount:Amount(total)},total).unwrap();assert_eq!(pools(total,[6000,2500,500,1000]).unwrap().0,[60_000,25_000,5_000,10_000].map(|v|v*100_000_000));let prior=300u128*100_000_000;l.apply(k(31),Operation::Claim{version:k(1),entitlement:k(4),beneficiary:k(5),amount:Amount(prior)},total-prior).unwrap();l.apply(k(32),Operation::Beneficiary{version:k(1),entitlement:k(4),old:k(5),new:k(33),sequence:1},total-prior).unwrap();l.apply(k(34),Operation::Retire{version:k(1)},total-prior).unwrap();assert!(l.apply(k(35),Operation::Claim{version:k(1),entitlement:k(4),beneficiary:k(5),amount:Amount(1)},total-prior-1).is_err());let remaining=900u128*100_000_000;let op=Operation::Claim{version:k(1),entitlement:k(4),beneficiary:k(33),amount:Amount(remaining)};assert!(l.apply(k(36),op.clone(),total-prior-remaining).unwrap());assert!(!l.apply(k(36),op,total-prior-remaining).unwrap());assert!(l.apply(k(37),Operation::Claim{version:k(1),entitlement:k(4),beneficiary:k(33),amount:Amount(1)},total-prior-remaining-1).is_err());assert!(l.apply(k(38),Operation::Refund{order:k(16),amount:Amount(1)},total-prior-remaining).is_err());l.validate(total-prior-remaining).unwrap();}
#[test]fn atom_splits_turnover_and_exact_inheritance(){let sum=10_001u128;let mut previous=[0;4];let mut deltas=[0;4];for n in 1..=sum {let p=pools(n,[6000,2500,500,1000]).unwrap().0;for i in 0..4{deltas[i]+=p[i]-previous[i];}previous=p;}assert_eq!(deltas,pools(sum,[6000,2500,500,1000]).unwrap().0);assert!(pools(CAP as u128*10_000,[6000,2500,500,1000]).is_ok());let graph=vec![(k(1),vec![(k(2),50),(k(3),50)]),(k(2),vec![(k(4),100)]),(k(3),vec![(k(4),100)])];assert_eq!(inherit(&graph,k(1),100).unwrap(),vec![(k(4),100)]);assert!(inherit(&[(k(1),vec![(k(2),50),(k(2),50)])],k(1),100).is_err());assert!(inherit(&[(k(1),vec![(k(2),100)]),(k(2),vec![(k(1),100)])],k(1),100).is_err());}
